raw:
{
  "summary": [
    {
      "text": "Преобразование Больцмана сводит уравнение в частных производных к обычному дифференциальному.",
      "claims": [
        "c1",
        "c2"
      ]
    },
    {
      "text": "Введение новой переменной s позволяет найти решение для давления в виде интеграла.",
      "claims": [
        "c3",
        "c4"
      ]
    }
  ],
  "how_it_works": [
    {
      "text": "Уравнение пьезопроводности решается с помощью преобразования Больцмана.",
      "claims": [
        "c1"
      ]
    },
    {
      "text": "Вводится новая переменная s, зависящая от радиуса r, времени t и свойств пласта.",
      "claims": [
        "c2"
      ]
    },
    {
      "text": "Вычисляются частные производные s по r и t.",
      "claims": [
        "c5",
        "c6"
      ]
    },
    {
      "text": "Исходное уравнение выражается через новую переменную s.",
      "claims": [
        "c7"
      ]
    },
    {
      "text": "Подстановка производных приводит к упрощению уравнения.",
      "claims": [
        "c8"
      ]
    },
    {
      "text": "Полученное уравнение является обычным дифференциальным уравнением.",
      "claims": [
        "c9"
      ]
    },
    {
      "text": "Вводится замена переменной для решения ОДУ.",
      "claims": [
        "c10"
      ]
    },
    {
      "text": "Уравнение разделяется и интегрируется.",
      "claims": [
        "c11",
        "c12"
      ]
    },
    {
      "text": "Константа интегрирования находится из граничного условия линейного источника.",
      "claims": [
        "c13",
        "c14"
      ]
    },
    {
      "text": "Финальное решение представляет собой интеграл от экспоненты.",
      "claims": [
        "c15",
        "c16"
      ]
    }
  ],
  "steps": [
    {
      "text": "Определяется переменная s как отношение r^2 к 4kt.",
      "claims": [
        "c2"
      ]
    },
    {
      "text": "Вычисляются производные ds/dr и ds/dt.",
      "claims": [
        "c5",
        "c6"
      ]
    },
    {
      "text": "Уравнение пьезопроводности переписывается через s.",
      "claims": [
        "c7"
      ]
    },
    {
      "text": "Уравнение упрощается до ОДУ вида d/ds(s dp/ds) = -s dp/ds.",
      "claims": [
        "c8"
      ]
    },
    {
      "text": "Решается ОДУ методом разделения переменных.",
      "claims": [
        "c10",
        "c11"
      ]
    },
    {
      "text": "Определяется константа C2 через граничное условие при r стремится к 0.",
      "claims": [
        "c13",
        "c14"
      ]
    },
    {
      "text": "Интегрируется полученное выражение для нахождения давления p.",
      "claims": [
        "c15"
      ]
    }
  ],
  "examples": [],
  "numbers": [
    {
      "text": "В формуле для s используются коэффициенты 4 и 2.",
      "claims": [
        "c2",
        "c5"
      ]
    },
    {
      "text": "В граничном условии используется коэффициент 2pi.",
      "claims": [
        "c13"
      ]
    }
  ],
  "formulas": [
    {
      "unit": "u087-23",
      "latex": "s = \\frac{r^2}{4(\\text{Diffusivity constant})t} = \\frac{\\phi \\mu c r^2}{4kt}",
      "vars": [
        {
          "sym": "s",
          "meaning": "новая переменная",
          "unit": "-"
        },
        {
          "sym": "r",
          "meaning": "радиус",
          "unit": "m"
        },
        {
          "sym": "t",
          "meaning": "время",
          "unit": "s"
        },
        {
          "sym": "\\phi",
          "meaning": "пористость",
          "unit": "-"
        },
        {
          "sym": "\\mu",
          "meaning": "вязкость",
          "unit": "Pa*s"
        },
        {
          "sym": "c",
          "meaning": "сжимаемость",
          "unit": "1/Pa"
        },
        {
          "sym": "k",
          "meaning": "проницаемость",
          "unit": "m^2"
        }
      ]
    },
    {
      "unit": "u087-25",
      "latex": "\\frac{\\partial s}{\\partial r} = \\frac{\\phi \\mu c r}{2kt}",
      "vars": [
        {
          "sym": "\\\\frac{\\\\partial s}{\\\\partial r}",
          "meaning": "частная производная s по r",
          "unit": "1/m"
        }
      ]
    },
    {
      "unit": "u087-27",
      "latex": "\\frac{\\partial s}{\\partial t} = - \\frac{\\phi \\mu c r^2}{4kt^2}",
      "vars": [
        {
          "sym": "\\\\frac{\\\\partial s}{\\\\partial t}",
          "meaning": "частная производная s по t",
          "unit": "1/s"
        }
      ]
    },
    {
      "unit": "u088-08",
      "latex": "\\frac{d}{ds} \\left( s \\frac{dp}{ds} \\right) = -s \\frac{dp}{ds}",
      "vars": [
        {
          "sym": "p",
          "meaning": "давление",
          "unit": "Pa"
        }
      ]
    },
    {
      "unit": "u088-19",
      "latex": "p' = C_2 \\frac{e^{-s}}{s}",
      "vars": [
        {
          "sym": "p'",
          "meaning": "производная давления по s",
          "unit": "Pa"
        },
        {
          "sym": "C_2",
          "meaning": "константа интегрирования",
          "unit": "Pa"
        }
      ]
    },
    {
      "unit": "u088-30",
      "latex": "p_{r,t} = p_i - \\frac{q\\mu}{4\\pi kh} \\int_{\\infty}^{x} \\frac{e^{-s}}{s} ds",
      "vars": [
        {
          "sym": "p_{r,t}",
          "meaning": "давление в точке r и время t",
          "unit": "Pa"
        },
        {
          "sym": "p_i",
          "meaning": "начальное давление",
          "unit": "Pa"
        },
        {
          "sym": "q",
          "meaning": "расход",
          "unit": "m^3/s"
        },
        {
          "sym": "h",
          "meaning": "мощность пласта",
          "unit": "m"
        }
      ]
    }]}
